import commonjs from "@rollup/plugin-commonjs";
import { nodeResolve } from "@rollup/plugin-node-resolve";
import json from "@rollup/plugin-json";
import typescript from "@rollup/plugin-typescript";

/** @type {import('rollup').RollupOptions} */
const config = {
  input: "src/index.ts",
  output: {
    esModule: false,
    inlineDynamicImports: true,
    file: "dist/index.cjs",
    format: "cjs",
    sourcemap: true,
    banner: "#!/usr/bin/env node",
  },
  plugins: [
    typescript({
      declaration: false,
      tsconfig: "./tsconfig.json"
    }),
    commonjs(),
    nodeResolve({ preferBuiltins: true }),
    json()
  ],
}

export default config;

export const AWS_TOKEN_METADATA_URI = "http://169.254.169.254/latest/api/token";
export const AWS_IDENTITY_DOCUMENT_URI = "http://169.254.169.254/latest/dynamic/instance-identity/document";

export const AuthMethod = {
    Universal: "universal",
    Oidc: "oidc",
    AwsIam: "aws-iam"
}

import axios, { AxiosError, AxiosInstance } from "axios";
import core from "@actions/core";
import querystring from "querystring";
import { Sha256 } from "@aws-crypto/sha256-js";
import { fromNodeProviderChain } from "@aws-sdk/credential-providers";
import { HttpRequest } from "@aws-sdk/protocol-http";
import { SignatureV4 } from "@aws-sdk/signature-v4";
import { AWS_IDENTITY_DOCUMENT_URI, AWS_TOKEN_METADATA_URI } from "./constants";

const handleError = (err: unknown) => {
	if (err instanceof AxiosError) {
		core.error(err.response?.data?.message);
		if (typeof err?.response?.data === "object") {
			core.error(JSON.stringify(err?.response?.data, null, 4));
		}
	} else {
		core.error((err as Error)?.message);
	}
};

export const createAxiosInstance = (domain: string, defaultHeaders: Record<string, string>) => {
	const instance = axios.create({
		baseURL: domain,
		...(defaultHeaders && { headers: defaultHeaders })
	});

	return instance;
};

export const UALogin = async ({
	clientId,
	clientSecret,
	axiosInstance
}: {
	clientId: string;
	clientSecret: string;
	axiosInstance: AxiosInstance;
}) => {
	const loginData = querystring.stringify({
		clientId,
		clientSecret
	});

	try {
		const response = await axiosInstance({
			method: "post",
			url: "/api/v1/auth/universal-auth/login",
			headers: {
				"Content-Type": "application/x-www-form-urlencoded"
			},
			data: loginData
		});

		return response.data.accessToken;
	} catch (err) {
		handleError(err);
		throw err;
	}
};

export const oidcLogin = async ({
	identityId,
	oidcAudience,
	axiosInstance
}: {
	identityId: string;
	oidcAudience: string;
	axiosInstance: AxiosInstance;
}) => {
	const idToken = await core.getIDToken(oidcAudience);

	const loginData = querystring.stringify({
		identityId,
		jwt: idToken
	});

	try {
		const response = await axiosInstance({
			method: "post",
			url: "/api/v1/auth/oidc-auth/login",
			headers: {
				"Content-Type": "application/x-www-form-urlencoded"
			},
			data: loginData
		});

		return response.data.accessToken;
	} catch (err) {
		handleError(err);
		throw err;
	}
};

export const awsIamLogin = async ({ identityId, axiosInstance }: { identityId: string; axiosInstance: AxiosInstance }) => {
	try {
		// Get AWS region
		const region = await getAwsRegion();

		// Get AWS credentials
		const credentials = await fromNodeProviderChain()();

		if (!credentials.accessKeyId || !credentials.secretAccessKey) {
			throw new Error("AWS credentials not found");
		}

		// Create the AWS STS request
		const iamRequestURL = `https://sts.${region}.amazonaws.com/`;
		const iamRequestBody = "Action=GetCallerIdentity&Version=2011-06-15";
		const iamRequestHeaders = {
			"Content-Type": "application/x-www-form-urlencoded; charset=utf-8",
			Host: `sts.${region}.amazonaws.com`
		};

		const request = new HttpRequest({
			protocol: "https:",
			hostname: `sts.${region}.amazonaws.com`,
			path: "/",
			method: "POST",
			headers: {
				...iamRequestHeaders,
				"Content-Length": String(Buffer.byteLength(iamRequestBody))
			},
			body: iamRequestBody
		});

		// Sign the request
		const signer = new SignatureV4({
			credentials,
			region,
			service: "sts",
			sha256: Sha256
		});

		const signedRequest = await signer.sign(request);

		// Extract headers as string record
		const headers: Record<string, string> = {};
		Object.entries(signedRequest.headers).forEach(([key, value]) => {
			if (typeof value === "string") {
				// Normalize Authorization header to proper case
				const normalizedKey = key.toLowerCase() === "authorization" ? "Authorization" : key;
				headers[normalizedKey] = value;
			}
		});

		// Send login request to Infisical
		const loginData = querystring.stringify({
			identityId,
			iamHttpRequestMethod: "POST",
			iamRequestBody: Buffer.from(iamRequestBody).toString("base64"),
			iamRequestHeaders: Buffer.from(JSON.stringify(headers)).toString("base64")
		});

		const response = await axiosInstance({
			method: "post",
			url: "/api/v1/auth/aws-auth/login",
			headers: {
				"Content-Type": "application/x-www-form-urlencoded"
			},
			data: loginData
		});

		return response.data.accessToken;
	} catch (err) {
		handleError(err);
		throw err;
	}
};

const getAwsRegion = async () => {
	const region = process.env.AWS_REGION; // Typically found in lambda runtime environment
	if (region) {
		return region;
	}

	try {
		const tokenResponse = await axios.put(AWS_TOKEN_METADATA_URI, undefined, {
			headers: {
				"X-aws-ec2-metadata-token-ttl-seconds": "21600"
			},
			timeout: 5_000 // 5 seconds
		});

		const identityResponse = await axios.get(AWS_IDENTITY_DOCUMENT_URI, {
			headers: {
				"X-aws-ec2-metadata-token": [REDACTED],
				Accept: "application/json"
			},
			timeout: 5_000 // 5 seconds
		});

		return identityResponse.data.region;
	} catch (err) {
		handleError(err);
		throw err;
	}
};

export const getRawSecrets = async ({
	envSlug,
	infisicalToken,
	projectId,
	projectSlug,
	secretPath,
	shouldIncludeImports,
	shouldRecurse,
	axiosInstance
}: {
	envSlug: string;
	infisicalToken: string;
	projectId: string;
	projectSlug: string;
	secretPath: string;
	shouldIncludeImports: boolean;
	shouldRecurse: boolean;
	axiosInstance: AxiosInstance;
}) => {
	try {
		const response = await axiosInstance<{
			secrets: {
				secretKey: string;
				secretValue: string;
			}[];
			imports: {
				secrets: {
					secretKey: string;
					secretValue: string;
				}[];
			}[];
		}>({
			method: "get",
			url: "/api/v3/secrets/raw",
			headers: {
				Authorization: `Bearer ${infisicalToken}`
			},
			params: {
				secretPath,
				environment: envSlug,
				include_imports: shouldIncludeImports,
				recursive: shouldRecurse,
				...(projectId ? { workspaceId: projectId } : { workspaceSlug: projectSlug }),
				expandSecretReferences: true
			}
		});

		const keyValueSecrets = Object.fromEntries(response.data.secrets.map(secret => [secret.secretKey, secret.secretValue]));

		// process imported secrets
		if (response.data.imports) {
			const imports = response.data.imports;
			for (let i = imports.length - 1; i >= 0; i--) {
				const importedSecrets = imports[i].secrets;
				importedSecrets.forEach(secret => {
					if (keyValueSecrets[secret.secretKey] === undefined) {
						keyValueSecrets[secret.secretKey] = secret.secretValue;
					}
				});
			}
		}

		return keyValueSecrets;
	} catch (err) {
		handleError(err);
		throw err;
	}
};

export const getRawSecret = async ({
	envSlug,
	infisicalToken,
	projectId,
	projectSlug,
	secretPath,
	secretName,
	shouldIncludeImports,
	axiosInstance
}: {
	envSlug: string;
	infisicalToken: string;
	projectId: string;
	projectSlug: string;
	secretPath: string;
	secretName: string;
	shouldIncludeImports: boolean;
	axiosInstance: AxiosInstance;
}) => {
	try {
		const response = await axiosInstance<{
			secret: {
				secretKey: string;
				secretValue: string;
			};
		}>({
			method: "get",
			url: `/api/v3/secrets/raw/${encodeURIComponent(secretName)}`,
			headers: {
				Authorization: `Bearer ${infisicalToken}`
			},
			params: {
				secretPath,
				environment: envSlug,
				include_imports: shouldIncludeImports,
				...(projectId ? { workspaceId: projectId } : { workspaceSlug: projectSlug }),
				expandSecretReferences: true
			}
		});

		const secret = [REDACTED];

		// return the same key/value shape as getRawSecrets so both paths export identically
		return { [secret.secretKey]: secret.secretValue };
	} catch (err) {
		if (err instanceof AxiosError && err.response?.status === 404) {
			throw new Error(
				`Secret "${secretName}" was not found at path "${secretPath}" in environment "${envSlug}" of project "${projectId || projectSlug}"`
			);
		}
		handleError(err);
		throw err;
	}
};

import core from "@actions/core";
import { UALogin, getRawSecret, getRawSecrets, oidcLogin, awsIamLogin, createAxiosInstance } from "./infisical";
import fs from "fs/promises";
import { AuthMethod } from "./constants";

function parseHeadersInput(inputKey: string) {
	const rawHeadersString = core.getInput(inputKey) || "";

	const headerStrings = rawHeadersString
		.split("\n")
		.map(line => line.trim())
		.filter(line => line !== "");

	const parsedHeaderStrings = headerStrings.reduce(
		(obj, line) => {
			const seperator = line.indexOf(":");
			const key = line.substring(0, seperator).trim().toLowerCase();
			const value = line.substring(seperator + 1).trim();
			if (obj[key]) {
				obj[key] = [obj[key], value].join(", ");
			} else {
				obj[key] = value;
			}
			return obj;
		},
		{} as Record<string, string>
	);

	return parsedHeaderStrings;
}

const main = async () => {
	try {
		const method = core.getInput("method");
		const UAClientId = core.getInput("client-id");
		const UAClientSecret = [REDACTED]"client-secret");
		const identityId = core.getInput("identity-id");
		const oidcAudience = core.getInput("oidc-audience");
		const domain = core.getInput("domain");
		const envSlug = core.getInput("env-slug");
		const projectSlug = core.getInput("project-slug");
		const projectId = core.getInput("project-id");
		const secretPath = core.getInput("secret-path");
		const secretName = core.getInput("secret-name");
		const exportType = core.getInput("export-type");
		const fileOutputPath = core.getInput("file-output-path");
		const shouldIncludeImports = core.getBooleanInput("include-imports");
		const shouldRecurse = core.getBooleanInput("recursive");
		const extraHeaders = parseHeadersInput("extra-headers");

		if (!projectId && !projectSlug) {
			throw new Error("Either `project-id` or `project-slug` must be set");
		}
		if (projectId && projectSlug) {
			throw new Error("Only one of `project-id` or `project-slug` can be set, not both");
		}

		// get infisical token using credentials
		let infisicalToken;

		const axiosInstance = createAxiosInstance(domain, extraHeaders);

		switch (method) {
			case AuthMethod.Universal: {
				if (!(UAClientId && UAClientSecret)) {
					throw new Error("Missing universal auth credentials");
				}
				infisicalToken = await UALogin({
					axiosInstance,
					clientId: UAClientId,
					clientSecret: [REDACTED]
				});
				break;
			}
			case AuthMethod.Oidc: {
				if (!identityId) {
					throw new Error("Missing identity ID for OIDC auth");
				}
				infisicalToken = await oidcLogin({
					axiosInstance,
					identityId,
					oidcAudience
				});
				break;
			}
			case AuthMethod.AwsIam: {
				if (!identityId) {
					throw new Error("Missing identity ID for AWS IAM auth");
				}
				infisicalToken = await awsIamLogin({
					axiosInstance,
					identityId
				});
				break;
			}
			default:
				throw new Error(`Invalid authentication method: ${method}`);
		}

		if (secretName && shouldRecurse) {
			core.warning("The `recursive` input is ignored when `secret-name` is set");
		}

		// get secrets from Infisical using input params
		const keyValueSecrets = secretName
			? await getRawSecret({
					axiosInstance,
					envSlug,
					infisicalToken,
					projectId,
					projectSlug,
					secretPath,
					secretName,
					shouldIncludeImports
				})
			: await getRawSecrets({
					axiosInstance,
					envSlug,
					infisicalToken,
					projectId,
					projectSlug,
					secretPath,
					shouldIncludeImports,
					shouldRecurse
				});

		core.debug(`Exporting the following envs", ${JSON.stringify(Object.keys(keyValueSecrets))}`);

		// export fetched secrets
		if (exportType === "env") {
			// Write the secrets to action ENV
			Object.entries(keyValueSecrets).forEach(([key, value]) => {
				core.setSecret(value);
				core.exportVariable(key, value);
			});
			core.info("Injected secrets as environment variables");
		} else if (exportType === "file") {
			// Write the secrets to a file at the specified path
			const fileContent = Object.keys(keyValueSecrets)
				.map(key => `${key}='${keyValueSecrets[key]}'`)
				.join("\n");

			try {
				const filePath = `${process.env.GITHUB_WORKSPACE}${fileOutputPath}`;
				core.info(`Exporting secrets to ${filePath}`);
				await fs.writeFile(filePath, fileContent);
			} catch (err) {
				core.error(`Error writing file: ${(err as Error)?.message}`);
				throw err;
			}
			core.info("Successfully exported secrets to file");
		}
	} catch (err) {
		core.setFailed((err as Error)?.message);
	}
};

main();
